import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { DatabaseSync } from 'node:sqlite';
import { chromium } from 'playwright';

const root = process.cwd();
const read = p => fs.readFileSync(path.join(root,p),'utf8');
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p = s => `<p>${s}</p>`;
const list = a => `<ul>${a.map(s=>`<li>${s}</li>`).join('')}</ul>`;
const table = (heads, rows) => `<table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const note = s => `<aside>${s}</aside>`;
const sub = s => `<h3>${s}</h3>`;
const code = s => `<pre>${esc(s)}</pre>`;
const pages=[];
const add=(title,body,source='')=>pages.push({title,body,source});
const database = new DatabaseSync(path.join(root,'data/nvo.sqlite'),{readOnly:true});
const settings=JSON.parse(database.prepare('SELECT data FROM settings WHERE id=1').get().data);
const all=database.prepare('SELECT data FROM entries').all().map(r=>JSON.parse(r.data));
const live=e=>e.active&&e.status!=='draft'&&!e.demo&&(!e.startsAt||Date.parse(e.startsAt)<=Date.now())&&(!e.endsAt||Date.parse(e.endsAt)>Date.now());
const cats=new Set(all.filter(e=>e.kind==='categories'&&live(e)).map(e=>e.id));
const meals=all.filter(e=>e.kind==='meals'&&live(e)&&(!e.category||cats.has(e.category)));
const counts=database.prepare('SELECT kind,count(*) AS n FROM entries GROUP BY kind').all();
const accounts=database.prepare('SELECT count(*) AS n FROM social_accounts').get().n;
const schema=database.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all().map(({name})=>({name,columns:database.prepare(`PRAGMA table_info("${name.replaceAll('"','""')}")`).all()}));
database.close();
const pkg=JSON.parse(read('package.json'));
const lock=JSON.parse(read('package-lock.json'));

add('NVO Restaurant',`<div class="cover-label">APPLICATION DOSSIER</div><h1>From the customer<br>experience to the<br>backend.</h1><div class="gold-rule"></div><p class="lead">Product, architecture, administration, integrations and operating guide</p><div class="cover-meta">Prepared 28 September 2026<br>Project version ${esc(pkg.version)} · Local implementation snapshot</div><div class="stats"><div><b>${meals.length}</b>public menu entries</div><div><b>${schema.length}</b>database tables</div><div><b>53 / 53</b>automated tests passed</div></div>${note('Prepared from the application source, a read-only database inspection, project documentation and local verification. This is a description of the current implementation, not a declaration of completed production deployment. Passwords, tokens and customer records are excluded.')}`);
add('Reading this report',p('NVO combines a bilingual restaurant website with a staff workspace for menu management, order requests, coupons, content and social publishing. The aim is to help customers discover food, take action through WhatsApp, and return through offers and useful restaurant updates.')+sub('Status language')+table(['Label','Meaning'],[['Implemented','Present in the inspected source and local application. This does not by itself prove live provider operation.'],['Configured locally','A value exists in the current restaurant database or workspace.'],['Awaiting activation','Code exists, but hosting, account authorization, credentials or live verification remain.'],['Outstanding','A requested capability is incomplete or absent from the current implementation.']])+sub('Scope and evidence')+list(['Fresh verification on 28 September 2026: npm test completed with 53 passes and zero failures. Tests use isolated data and simulated publishing providers.','Earlier browser, accessibility and Lighthouse reports are stored under artifacts/. Their historical results are identified separately; the browser suite was not rerun for this document.','The report covers the implemented product and relevant gaps from the original brief. It does not reproduce the entire source code, credentials, or personal customer data.','Current business settings and record totals are a snapshot; staff changes after generation will not update this PDF automatically.'])+sub('Document map')+p('Business profile and status → architecture and frontend → orders and coupons → admin and integrations → security, operations and launch gaps → detailed API, schema, environment and source references.'),'README.md; instructions.txt; research/README.md; tests/*.test.ts');
add('Restaurant profile and current data',table(['Field','Current local value'],[['Public name',settings.name],['Location',settings.address],['WhatsApp order destination','+'+settings.whatsapp],['Currency',settings.currency+' / FCFA'],['Map coordinates',settings.latitude+', '+settings.longitude],['Map link',settings.mapsUrl],['Instagram profile',settings.instagram||'Not configured'],['Business email',settings.email||'Not yet provided'],['Opening hours',settings.hours||'Not yet provided'],['Public price setting',settings.showPrices?'Enabled; individual meals can override':'Hidden globally; individual meals can override'],['Show sample editorial content',settings.previewContent?'Enabled':'Disabled'],['Referral configuration',`${settings.referralEnabled?'Enabled':'Disabled'}; ${settings.referralClaimMinutes}-minute claim window`],['Stored social accounts',String(accounts)]])+p('The location and WhatsApp number were supplied by the project owner. The map entrance, live WhatsApp routing, account ownership, final opening hours and policies still need restaurant confirmation. The Instagram URL is a website link, not evidence that publishing authorization is connected.')+note('Brand direction: royal blue, white and gold; seafood and Nigerian cuisine. The selected locality is Agblangandan, Cotonou, Bénin. Earlier printed materials contain a different address; the current owner-selected location takes precedence.'),'data/nvo.sqlite settings (read-only); lib/seed.ts; research/restaurant-research.md; research/current-menu-and-seo.md');
add('Feature inventory and delivery status',table(['Area','Current implementation','Remaining boundary'],[['Customer site','Home, menu, dish pages, gallery, story, contact, events, news, specials, offers, loyalty and testimonials','Final restaurant content and business policies'],['Ordering','Persistent cart, server quotes, saved requests, prepared WhatsApp messages','Customer presses Send; no online payment gateway'],['Reservations','Saved request and WhatsApp handoff; staff status changes','Staff must confirm availability'],['Coupons','Named cards, claim rules, wallet, expiry, counter redemption','Verified customer identity and automatic hold release'],['Referrals','Links, visit tracking, claim window','Automatic referrer reward on a completed sale'],['Staff tools','Content, photos, orders, settings, analytics, publishing desk','Staff-account management and password recovery UI'],['Social publishing','Connections, captions, queue, schedules, retries and receipts','Real provider authorization and live acceptance checks'],['Translation','Local English/French model worker','Human review of food names and offer terms'],['Hosting','Local custom Node server; Oracle deployment templates','Oracle access, public deployment, backups and restore test']])+sub('Stored records versus public content')+p(`The database holds ${counts.map(r=>`${r.n} ${esc(r.kind)}`).join(', ')}. Those totals include drafts, archived items and sample content. The inspected catalogue rules expose ${meals.length} live meal entries across ${cats.size} live categories.`)+note('The original 63-section brief is broader than the delivered implementation. “Built locally” must not be read as “every requested feature complete” or “social posting verified in production”.'),'README.md; lib/catalog.ts; lib/types.ts; current database entry aggregates');
add('Architecture and request flow',`<div class="flow"><div>Customer or staff browser<br><small>React UI · cart · language · consent</small></div><span>HTTPS requests ↓</span><div>Reverse proxy on the hosted server<br><small>Planned Caddy TLS and verified client-IP forwarding</small></div><span>Local HTTP ↓</span><div>server.mjs → Next.js App Router<br><small>Socket-IP signing · pages · API routes · authentication</small></div><span>Validated business operations ↓</span><div>SQLite + persistent data directories<br><small>Restaurant records · uploads · models · publishing queue</small></div><span>Background work ↓</span><div>Local translation worker / social publishing worker<br><small>OPUS models / authorized provider APIs</small></div></div>`+p('The application is one deployable Node service rather than separate frontend and backend projects. Pages can obtain restaurant data on the server, while interactive client components call JSON endpoints. The root layout loads the public catalogue and initializes the client provider.')+p('server.mjs loads environment configuration, prepares Next.js, and binds to 127.0.0.1 by default on port 3000. It signs the verified network address on each request. Production uses this entry point rather than bypassing it with a plain framework server.')+note('SQLite and locally stored files require a durable filesystem. The current deployment design is a single server; multiple independent replicas with their own files would not share restaurant state.'),'server.mjs; app/layout.tsx; components/provider.tsx; lib/db.ts; instrumentation.ts');
add('Technology stack and project layout',table(['Layer','Package / runtime','Purpose'],[['Server runtime','Node.js >=24','Native SQLite and application process'],...['next','react','react-dom','zod','sharp','qrcode','@huggingface/transformers','onnxruntime-web'].map(n=>[n,lock.packages?.['node_modules/'+n]?.version||pkg.dependencies[n],({'next':'Pages, rendering, routes, images, metadata','react':'Interactive UI','react-dom':'Browser rendering','zod':'Runtime input validation','sharp':'Social image preparation','qrcode':'Coupon verification QR codes','@huggingface/transformers':'Translation pipelines','onnxruntime-web':'CPU/WASM inference'})[n]])])+table(['Directory / file','Responsibility'],[['app/','Page routes, API routes, metadata and shared styles'],['components/','Customer pages, menu, cart UI, admin, coupons and publishing tools'],['lib/','Database, authentication, catalogue, validation and business logic'],['lib/social/','Account authorization, provider calls, captions, jobs and delivery'],['public/','Deployed images, fonts and videos'],['data/','SQLite, uploaded media, model files and generated social images'],['scripts/','Setup, imports, fixtures, audits and workers'],['tests/ and artifacts/','Automated checks and local evidence'],['research/ and instructions.txt','Requirements, decisions and operating notes'],['deploy/oracle/','Prepared service/proxy/environment templates; not deployed']]),'package.json; package-lock.json; source directory inventory');
add('Frontend pages and navigation',table(['Route','Customer purpose'],[['/','Restaurant introduction, food highlights, specials and calls to action'],['/menu and /menu/[id]','Search/filter dishes, view details, choose quantities'],['/cart','Review selection, customer details, coupon, delivery/pickup/dine-in'],['/reservation','Request a table with date, time and party size'],['/specials and /specials/[id]','Discover current meals or kitchen spotlights and enquire'],['/offers; /promotions','Coupon experience; old promotions alias redirects to offers'],['/referral and /r/[code]','Create/share referral links and record invited visits'],['/news, /events and detail URLs','Published restaurant content and occasions'],['/about, /gallery, /contact','Restaurant story, photographs, film, address and map'],['/loyalty and /testimonials','Staff-managed recognition and guest stories'],['/subscribe','Consent-based WhatsApp marketing signup instructions'],['/privacy and /terms','Current policy copy; owner review required'],['/admin','Authenticated staff workspace']])+p('French public URLs use /fr; English uses the unprefixed canonical route. /en aliases redirect permanently. API and admin endpoints are not separate translated deployments. Unknown content returns a real not-found response.')+p('The design uses responsive layouts, a mobile-friendly navigation system, persistent cart controls, a vector chef host, optional spoken welcome, motion preferences and reduced-motion support. Content and offer eligibility are enforced in the backend, not just by hiding buttons.'),'app/[...slug]/page.tsx; app/page.tsx; proxy.ts; components/shell.tsx; components/chef.tsx; components/motion.tsx');
add('Menu, media and bilingual content',p(`The imported PDF menu defines 77 dishes, portions and extras in 10 categories. The current database exposes ${meals.length} live meal entries; ${meals.filter(e=>e.price==null).length} have no fixed price and ${meals.filter(e=>e.preorder).length} are marked for pre-order.`)+list(['Categories include rice, other meals, pepper soups, Nigerian soups, swallow, barbecue, shawarma, seafood, seafood boil packages and extras.','Meal records support English/French titles and descriptions, category, photo, price visibility, availability, pre-order, featured state, badges and sorting.','Some differently priced portions were transcribed as separate entries because the supplied PDF did not identify their exact portion sizes. Staff can clarify the labels later.','Global and per-meal price visibility are applied by the public catalogue and quote logic. Unknown/hidden prices remain null; they are not treated as free.','Search supports English/French content and accent-insensitive matching. Dish pages include related choices and selection controls.','The importer previews before applying, creates a consistent SQLite backup and preserves staff edits and historical references. It does not reset the restaurant database.'])+sub('Media management')+p('Staff can upload JPEG, PNG or WebP images up to 8 MB. Server code checks basic file signatures and writes random filenames under data/uploads. Records track the original display name and public URL. Images referenced by entries, including drafts, cannot be deleted until references are replaced.')+p('NVO photographs are supplemented by labelled illustrative images with credits in lib/menu-photos.ts. Unsuitable or unavailable dish photos use a branded placeholder. The kitchen film loads on playback; local font files include their licenses.')+note('Upload signature checks are not a complete malware-scanning or image-content-moderation system. Avoid describing them as such.'),'lib/current-menu.ts; lib/menu-import.ts; lib/menu-photos.ts; components/menu.tsx; app/api/[...path]/route.ts');
add('Orders, quotes and reservations',`<div class="steps">Browse → Add to cart → Server quote → Save request → Open WhatsApp → Customer presses Send → Staff confirms</div>`+p('The browser stores meal identifiers and quantities. The backend reloads each meal, verifies its current availability and category, checks quantities, and calculates prices and coupon eligibility. Client-submitted totals are never the authority.')+list(['Order validation permits 1–40 distinct lines and quantities of 1–30 per line. Customer name, phone, notes, method and delivery address are collected as applicable.','A request key makes repeated submissions return the original order instead of silently creating another. The order and any coupon hold are committed transactionally.','After success, only submitted quantities are removed; new items added during the request are retained. Cart changes synchronize across tabs. A same-tab confirmation can be restored for 24 hours.','If any line price is unknown/hidden, the quote does not expose a calculable total or savings. Staff can enter a manual quote later.','Order states are request_created, accepted, fulfilled_paid and cancelled. Only staff-marked paid/fulfilled orders count as confirmed paid outcomes.','Reservation requests store name, phone, date, time, guests and message. Dates are evaluated in the Cotonou offset; staff can mark requested, confirmed or cancelled.'])+note('A stored order, reservation or WhatsApp click does not prove a message was sent, a table is confirmed, money was received, or food was delivered. Payment and fulfilment happen outside the website and require staff confirmation.')+p('There is no integrated card-payment checkout, automatic WhatsApp order-message sending, inventory management, delivery tracking or automatic restaurant booking allocation in this implementation.'),'lib/cart.ts; lib/pricing.ts; lib/validation.ts; components/pages.tsx; app/api/[...path]/route.ts');
add('Coupons, wallet and referrals',p('Campaign records define percentage, fixed-amount or free-meal rewards, minimum spend, discount cap, total claim capacity, opening/closing times, activation delay and validity period. Staff can publish, hide or archive a campaign.')+list(['Guests provide their name, claim an eligible offer and receive a unique NVO code. Issuance stores a snapshot of the terms so later campaign edits do not silently rewrite an issued reward.','The browser-linked wallet displays reward ownership, activation and expiry. A downloadable PNG card contains the name, code, validity, conditions and a staff-verification QR code.','Claiming is transactional. The current backend enforces one claim per browser identity and one network/IP per offer. Although the data model contains perCustomerLimit, current claim logic hard-caps browser claims at one.','Shared Wi-Fi is treated as one network. Changing network or clearing browser state can affect recognition; this is not verified human identity or an OTP-protected customer account.','A referral link records its owner and the invitee’s first visit. The configured claim window is checked server-side; self-referral and expired-window claims are rejected. Automatic rewards to the referrer after a sale remain outstanding.'])+sub('Counter redemption')+p('Authorized staff look up or scan a code, verify the customer name, enter receipt items and prices, calculate the discount and confirm payment. The server records a counter sale and atomically marks the coupon redeemed. Pending, expired, held or already-used rewards cannot be redeemed again.')+note('Current gaps: recurrent randomized coupon drops, cross-device wallets, verified customers, automatic referrer rewards and automated release of abandoned order-held coupons. The current implementation is a configurable campaign system, not the complete proposed growth engine.'),'lib/rewards.ts; lib/coupons.ts; lib/network.ts; components/coupons.tsx; components/coupon-desk.tsx');
add('Staff workspace and permissions',p('The admin desk groups menu and guest operations, restaurant storytelling, and tools/settings. It includes quick tasks, search/filtering, a mobile section selector, staff guidance and contextual empty/error states.')+table(['Role','Main permissions enforced in code'],[['Owner','Restaurant settings; all content, offers, operational and publishing controls'],['Manager','Content and campaigns; orders/reservations; coupon redemption; connect accounts and manage subscribers'],['Content','Non-campaign editorial/menu content, photos, translations, captions and publishing job actions'],['Service','Orders, manual quotes, reservations and coupon verification/redemption'],['Analyst','Read staff dashboard and activity data; no content or operational writes']])+p('Content edits include title, description, language variants, image, publication state and timing. Meals have category, pricing and availability controls. Editorial entries may choose website-only publishing, configured social defaults or explicit destinations.')+list(['Entry “delete” actions archive records to preserve historical order/coupon references, and cancel eligible unsent social jobs.','Only the owner changes core restaurant settings. Campaign create/archive controls are limited to owner and manager.','Owner/manager account management handles connecting, selecting defaults, disconnecting and subscriber removal. Content staff can work with permitted publishing tools but cannot connect accounts.','The initial staff account is bootstrapped from private environment configuration when no matching account exists. Changing bootstrap credentials does not change an existing account’s password.'])+note('Role checks are implemented, but a complete UI for creating/managing staff accounts and password recovery is still outstanding. A production owner-access recovery procedure must be established.'),'components/admin.tsx; components/social-admin.tsx; lib/auth.ts; app/api/[...path]/route.ts; app/api/admin/social/[action]/route.ts');
add('Publish everywhere: supported channels',table(['Destination','What the current code sends','Activation requirements'],[['Website','Published stories, specials and events','Valid staff login and content'],['Facebook','Photo and caption to selected Page','Meta developer app, permissions, owner authorization'],['Instagram','Photo container then publication','Professional account linked to selected Facebook Page and publishing access'],['TikTok','Photo upload into the creator’s inbox','Developer app, upload access, domain verification, per-post consent; finish in TikTok'],['WhatsApp','Approved marketing template to explicit subscribers','Cloud API sender, valid templates, webhook, authorized credentials and any required billing']])+p('The integration currently supports one photo per social post. Video/Reels, carousels, WhatsApp Status and WhatsApp Channel publishing are not implemented. A website Instagram link and an order-chat number are not equivalent to connected API accounts.')+sub('Staff flow')+p('Write a story, event or special → choose photo and language → review generated captions → choose destinations → save/publish now or set a future start → review individual delivery results. Connecting a new account does not automatically backfill old posts.')+note(`Current database snapshot: ${accounts} stored social accounts. Publishing code and mocked tests exist; real provider publishing has not been demonstrated for NVO. Provider rules and approval requirements must be rechecked during activation.`)+p('Approved account access, callback URLs, publicly accessible photos and a live HTTPS origin are essential. The application deliberately rejects localhost as a social publishing origin.'),'research/social-publishing.md; lib/social/accounts.ts; lib/social/providers.ts; lib/social/security.ts; components/social-admin.tsx');
add('Publishing queue and delivery reliability',p('Website entry changes and their publishing-queue changes are saved in one SQLite transaction. Jobs are durable records, with a unique entry/account pair, snapshotted payload, revision, next-attempt time and provider receipts.')+list(['The embedded worker starts through instrumentation.ts and polls every 10 seconds. An external worker mode is available on the same persistent host/database; off mode is for disabled delivery/testing.','Per-account leases prevent concurrent workers from publishing two jobs for the same account. The worker rechecks eligibility and account status before sending.','Future content waits until its scheduled time; drafts, sample entries, archived and expired content are excluded from new sends.','Transient/rate-limit rejections back off. Authentication failures pause affected accounts. One destination failing does not automatically stop another destination.','Interrupted or ambiguous final sends become needs_review rather than being blindly retried. Staff must check the destination before retrying uncertain outcomes.','Published posts are not automatically duplicated by subsequent edits. Editing or deleting content on the website does not edit/delete already delivered external posts.'])+table(['State group','Meaning'],[['queued / preparing / publishing','Waiting, preparing media/caption, or final provider send'],['retry / failed / needs_auth','Retry scheduled, failure requiring action, or reconnect needed'],['needs_review','Delivery may have happened; inspect before retry'],['processing / inbox','TikTok transfer/status stages; not proof of public publication'],['published / cancelled','Receipt-backed completion or unsent job cancelled']])+p('Social photos are converted with Sharp into 1080 × 1350 JPEG snapshots, reused when possible and served from unguessable URLs for seven days. Expired social media is cleaned up. These files must remain reachable by providers.')+note('The queue reduces duplication risk; it cannot guarantee exactly-once delivery across every third-party failure. A stopped host cannot publish on schedule.'),'lib/social/queue.ts; lib/social/worker.ts; lib/social/media.ts; scripts/social-worker.ts; instrumentation.ts');
add('WhatsApp subscriptions and translation',sub('Two distinct WhatsApp uses')+p('Ordering creates a prefilled wa.me link that the customer sends manually. Marketing is a separate Cloud API integration that sends approved templates only to explicitly subscribed recipients. Order and reservation contacts are not silently added to marketing lists.')+list(['On /subscribe, the guest acknowledges consent and sends JOIN NVO or ABONNER NVO. Merely opening the page/chat does not create a subscription.','Incoming webhooks must have a valid Meta signature and correct business phone ID. Message IDs are deduplicated.','STOP unsubscribes, cancels unsent messages and is rechecked before each recipient send. Older delayed subscribe events cannot overwrite a newer STOP.','Per-recipient records distinguish sent, delivered, read, failed, skipped and uncertain outcomes. A sender connection validates configured approved templates.'])+sub('Local translation')+p('The bilingual editor requests English/French translation through an authenticated API. A worker thread loads the two OPUS models using Transformers and ONNX WebAssembly CPU inference. Jobs are queued, input is chunked, results are cached by content hash in SQLite, and failed/timed-out requests show a retryable error.')+p('Automatic platform captions primarily use a local rule-based editorial engine; they do not require a paid AI key. An optional server-side AI caption integration exists when explicitly configured. Translation and caption generation are separate systems.')+note('Measured in the preceding local review: the model folder occupied about 271 MB and a standalone two-direction translation run peaked around 891 MB of process memory. This is a Windows test, not a production Linux sizing guarantee. Review translations before publishing.'),'components/subscribe.tsx; lib/social/whatsapp.ts; lib/translation.ts; scripts/translation-worker.mjs; lib/social/captions.ts');
add('Analytics, SEO and accessibility',sub('Guest Activity')+p('The dashboard reports consented visitor browsers, visits, page views, meal-unit additions/removals and action clicks. Visits use a 30-minute inactivity boundary; reports cover 30 days and group dates in Cotonou time. Browser identifiers are not verified people.')+p('Collection excludes recognized staff browsers, authenticated staff, local development, sample-preview mode, non-public pages and recognized bots. The client respects declined consent and Do Not Track. Earlier mixed analytics remain version 1 and are separated from corrected totals. Unknown bots or changed cookies can still affect counts.')+sub('Search implementation')+list(['Server-rendered English/French metadata, canonical URLs and language alternatives.','Restaurant, menu, menu-item and breadcrumb structured data are based on the public catalogue; hidden prices and invented reviews are excluded.','Sitemap uses eligible public entries and both languages; sample detail URLs are excluded. Sample-preview mode produces an empty sitemap and noindex metadata.','Robots excludes admin, API, cart and referral paths. Robots directives are not access control; backend authorization remains required.','Open Graph/Twitter imagery, favicon, image alt text, responsive images and local fonts support sharing and discoverability.'])+sub('Accessibility and performance')+p('The UI includes a skip link, labelled controls, responsive layouts and reduced-motion preferences. Existing browser suites run axe checks. The project records a prior local French-menu Lighthouse result of SEO 100, accessibility 100, best practices 100 and performance 80; those historical laboratory scores were not rerun for this report and do not guarantee live user performance or search rankings.'),'lib/analytics.ts; components/guest-activity.tsx; lib/seo.ts; app/sitemap.ts; app/robots.ts; research/current-menu-and-seo.md');
add('Backend security and data boundaries',table(['Control','Implementation and practical limit'],[['Staff authentication','Salted scrypt password hashes; random session tokens stored as digests; HttpOnly cookies and 12-hour sessions'],['Authorization','Server-enforced role checks on privileged reads/writes; UI visibility alone is not trusted'],['Request origin','Mutating application and publishing routes compare Origin with Host'],['Input validation','Zod schemas, field lengths, quantity/price/date limits and request-size checks'],['Rate limiting','SQLite counters for login and sensitive operations; effectiveness depends on reliable identity signals'],['Coupon IP trust','Custom server signs socket-derived IP; explicitly trusted reverse proxy must overwrite the selected header'],['Social tokens','AES-256-GCM encryption with account-bound context; stable private encryption key required'],['OAuth','Expiring state bound to browser cookie and staff account; one-time consumption'],['Webhooks','Meta HMAC signature checks and inbound deduplication'],['Media paths','Restricted local paths, generated filenames, file-size and basic signature checks'],['Public catalogue','Filters drafts/archived content and suppresses hidden prices'],['Browser headers','nosniff, DENY framing, referrer and permissions policies']])+note('This is a source-level description, not an independent security certification. Launch work still includes staff recovery, abuse controls, retention policy, backups, TLS/proxy validation and live integration acceptance.')+p('Private environment values, local admin credentials, database contents and uploaded customer-associated records must not be committed to a public repository. This report includes public business settings and schema names only; it omits passwords, encrypted tokens, session identifiers and customer rows.'),'lib/auth.ts; lib/validation.ts; lib/network.ts; lib/social/security.ts; lib/social/accounts.ts; next.config.ts; .gitignore');
add('Persistence, backup and recovery',p('SQLite uses WAL mode, foreign-key enforcement and a busy timeout. Content entries store their flexible fields as JSON while authentication, operations, coupon ownership, social jobs and audit trails have dedicated tables. Schema creation and incremental migrations run in lib/db.ts.')+table(['Location','Must persist / be recoverable'],[['data/nvo.sqlite','Restaurant data, staff access, sessions, orders, coupons, publishing state and settings'],['data/uploads/','Photos uploaded through the admin workspace'],['data/models/','Local translation models; can be re-downloaded but needed for translation'],['data/social-media/','Temporary publicly accessible snapshots used by in-flight publishing jobs'],['Private environment / encryption key','Provider credentials and key needed to decrypt saved connections'],['public/','Versioned website images, videos and fonts'],['.next/ and node_modules/','Build/runtime artifacts; regenerate on the target operating system']])+list(['Use SQLite’s online backup API or a coordinated stopped-service backup. Copying only a live database file can miss WAL transactions.','Back up uploaded files and private encryption configuration, with access controls appropriate to personal and credential data.','Keep a copy away from the application server/account. A backup on the same disk does not protect against loss of that server.','Restore to a separate environment and verify data, admin access, uploads, coupons and queue state before relying on the backup process.','Avoid accidentally publishing restored jobs during recovery tests; keep the test worker off. Preserve delivery history and review uncertain jobs.'])+note('Production backup scheduling, external storage selection and a demonstrated restore are still deployment tasks. The Oracle template documentation describes them but has not installed them.'),'lib/db.ts; scripts/import-menu.ts; deploy/oracle/README.md; .gitignore');
add('Hosting and deployment plan',p('The selected direction in the project discussion is Oracle Cloud Always Free, subject to successful account access and server availability. No Oracle server or public deployment has been verified in this workspace.')+table(['Setting','Prepared direction'],[['Server','Ubuntu ARM-compatible instance; proposed 2 OCPUs / 6 GB RAM / 50 GB boot disk, subject to console free eligibility'],['Runtime','Node 24; install dependencies and build on Linux rather than copying Windows binaries'],['Application','/srv/nvo; dedicated nvo service user; custom server on private port 3000'],['Public entry','Caddy HTTPS reverse proxy; temporary controlled hostname or final domain'],['Persistence','Preserve data directory and stable secret configuration across deployments'],['Client IP','Local reverse proxy overwrites X-Real-IP; application trusts only configured proxy addresses'],['Restart','systemd unit prepared for restart and boot startup'],['Backups / monitoring','Must be configured and validated before operational reliance']])+p('Files under deploy/oracle/ include nvo.service, Caddyfile, production.env.example and the deployment guide. They are preparation templates, not evidence of installed or tested Linux services. The environment template uses /etc/nvo/nvo.env and binds the application to loopback.')+p('The app does not require an expensive managed database at this size. It does require permanent disk and a process able to perform background work. Moving to serverless hosting would require changes to storage, background execution and the custom server’s IP handling.')+note('Oracle account/login issues are currently unresolved in the conversation. Free capacity, eligibility, idle reclamation and provider terms must be checked at provisioning time. This report does not promise uninterrupted free hosting or quote a live provider price.'),'deploy/oracle/*; server.mjs; README.md; prior local resource review');
