const htmlPath=path.join(root,'artifacts','NVO-Full-Application-Report.html');
const pdfPath=path.join(root,'NVO-Full-Application-Report.pdf');
fs.writeFileSync(htmlPath,html);
const executablePath=process.env.EDGE_PATH||'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
const browser=await chromium.launch({executablePath,headless:true});
try{
 const page=await browser.newPage({viewport:{width:1000,height:1200}});
 await page.goto(pathToFileURL(htmlPath).href);
 await page.evaluate(()=>document.fonts.ready);
 const overflow=await page.locator('.page').evaluateAll(nodes=>nodes.map((n,i)=>({page:i+1,bottom:n.querySelector('.content').getBoundingClientRect().bottom,footer:n.querySelector('.footer').getBoundingClientRect().top})).filter(r=>r.bottom>r.footer-10));
 if(overflow.length)throw new Error('Report content overlaps footer: '+JSON.stringify(overflow));
 await page.pdf({path:pdfPath,format:'A4',printBackground:true,preferCSSPageSize:true});
 await page.locator('.page').first().screenshot({path:path.join(root,'artifacts','NVO-report-cover.png')});
 await page.locator('.page').nth(4).screenshot({path:path.join(root,'artifacts','NVO-report-architecture.png')});
 console.log(JSON.stringify({pdf:pdfPath,html:htmlPath,pages:pages.length,bytes:fs.statSync(pdfPath).size,layoutOverflow:overflow.length}));
}finally{await browser.close()}
